package io.bfstats.sidecar

// What the tests take from the platform, for every target: a gunzip, files
// from the source tree (PARITY_DIR, MODELS_DIR: generated by the build), a
// scratch folder, and JUnit 4's Assert, so the tests read as they did on the
// JVM alone (kotlin.test's assertEquals puts the message last).

import kotlinx.io.files.Path
import kotlinx.io.files.SystemFileSystem
import kotlinx.io.files.SystemTemporaryDirectory

/** The bytes of a gzip file. */
expect fun gunzip(b: ByteArray): ByteArray

/** A file under the source tree, as bytes (gunzipped when it ends in .gz). */
fun readSourceFile(path: String): ByteArray {
  val b = FsFile(path).readBytes()
  return if (path.endsWith(".gz")) gunzip(b) else b
}

private var tempSeq = 0

/** A fresh folder under the system's temporary directory. */
fun tempDir(prefix: String): FsFile {
  val dir = FsFile(SystemTemporaryDirectory.toString(), "$prefix${wallMillis()}-${monoNanos()}-${tempSeq++}")
  SystemFileSystem.createDirectories(Path(dir.path))
  return dir
}

/** Every file under `dir`, as paths relative to it ('/'-separated). */
fun walkFiles(dir: FsFile): List<String> {
  val out = ArrayList<String>()
  fun walk(p: Path, rel: String) {
    for (c in SystemFileSystem.list(p)) {
      val r = if (rel.isEmpty()) c.name else "$rel/${c.name}"
      if (SystemFileSystem.metadataOrNull(c)?.isDirectory == true) walk(c, r) else out.add(r)
    }
  }
  walk(Path(dir.path), "")
  return out
}

/** JUnit 4's Assert, message first, over kotlin.test. */
object Assert {
  fun assertEquals(expected: Any?, actual: Any?) = kotlin.test.assertEquals(expected, actual)
  fun assertEquals(message: String?, expected: Any?, actual: Any?) = kotlin.test.assertEquals(expected, actual, message)
  fun assertEquals(expected: Double, actual: Double, delta: Double) {
    kotlin.test.assertTrue(kotlin.math.abs(expected - actual) <= delta || expected == actual, "expected:<$expected> but was:<$actual>")
  }
  fun assertTrue(condition: Boolean) = kotlin.test.assertTrue(condition)
  fun assertTrue(message: String?, condition: Boolean) = kotlin.test.assertTrue(condition, message)
  fun assertFalse(condition: Boolean) = kotlin.test.assertFalse(condition)
  fun assertFalse(message: String?, condition: Boolean) = kotlin.test.assertFalse(condition, message)
  fun assertNull(actual: Any?) = kotlin.test.assertNull(actual)
  fun assertNull(message: String?, actual: Any?) = kotlin.test.assertNull(actual, message)
}

/** One value handed between threads (ArrayBlockingQueue(1)'s put and poll). */
class Handoff<T> {
  private val lock = Lock()
  private var value: T? = null
  private var set = false
  fun put(v: T) { lock.withLock { value = v; set = true } }
  fun poll(timeoutMs: Long): T? {
    val until = monoNanos() + timeoutMs * 1_000_000
    while (true) {
      lock.withLock { if (set) return value }
      if (monoNanos() >= until) return null
      sleepMs(2)
    }
  }
}

/** A TcpConn over bytes in memory (ByteArrayInputStream), for the frame reader. */
class BytesConn(private val b: ByteArray) : TcpConn {
  private var at = 0
  override fun read(b: ByteArray, off: Int, len: Int): Int {
    if (at >= this.b.size) return -1
    val n = minOf(len, this.b.size - at)
    this.b.copyInto(b, off, at, at + n)
    at += n
    return n
  }
  override fun write(b: ByteArray) {}
  override fun close() {}
}
